def altura(no):
    if no is None:
        return 0
    return 1 + max(altura(no[1]), altura(no[2]))

def fatores(no):
    if no is None:
        return []
    fb = altura(no[1]) - altura(no[2])
    return [fb] + fatores(no[1]) + fatores(no[2])

dez = (10, (5, None, None), None)
vinte = (20, dez, (30, None, None))
arvore = (40, vinte, (60, None, None))
print(fatores(arvore))

